  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "high",
    "touches": [
      "wallet",
      "rpc_api"
    ],
    "why": "Mistakes in derivation path parsing or child key derivation could cause wallets to generate wrong addresses, misplace keys, or fail to find expected transaction outputs."
  }
}
